        charge_resp = requests.post(f'{API_BASE}/billing/streams/{stream_id}/charges', json={'amount_cents': EDITOR_SEAT_PRICE_CENTS, 'currency': 'USD', 'reason': 'editor_seat', 'principal': principal}, headers=HEADERS, timeout=15)
