        raise ValueError(f'venue_config must be one of {sorted(ALLOWED_CONFIGS)}')
    timeout_seconds = max(10, min(int(timeout_seconds), 1800))
    os.makedirs(STATE_DIR, exist_ok=True)
    marker_path = os.path.join(STATE_DIR, f'{event_id}.last_rebuild.json')
    with open(marker_path, 'w', encoding='utf-8') as fh:
        json.dump({'event_id': event_id, 'venue_config': venue_config, 'timeout_seconds': timeout_seconds, 'requested_at': datetime.now(timezone.utc).isoformat()}, fh)
    cmd = [PYTHON_BIN, SEATMAP_SCRIPT, '--event', event_id, '--config', venue_config]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_seconds, check=False)
    except subprocess.TimeoutExpired as exc:
        result = SeatMapRebuildResult(event_id=event_id, venue_config=venue_config, exit_code=-1, succeeded=False, stdout_tail=_tail(exc.stdout if isinstance(exc.stdout, str) else ''), stderr_tail=_tail(exc.stderr if isinstance(exc.stderr, str) else ''), timed_out=True)
        return asdict(result)
    result = SeatMapRebuildResult(event_id=event_id, venue_config=venue_config, exit_code=proc.returncode, succeeded=proc.returncode == 0, stdout_tail=_tail(proc.stdout), stderr_tail=_tail(proc.stderr))
    return asdict(result)

import os
import sqlite3
import stripe
from agents import function_tool
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
DB_PATH = os.environ.get('TICKETING_DB', '/var/lib/ticketing/orders.db')
VALID_REASONS = {'requested_by_customer', 'duplicate', 'fraudulent'}

@function_tool
def cancel_order_and_refund(order_id: str, reason: str='requested_by_customer', refund_amount_cents: int=0) -> dict:
    if reason not in VALID_REASONS:
        return {'ok': False, 'error': f'reason must be one of {sorted(VALID_REASONS)}'}
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        order = conn.execute('SELECT id, status, total_cents, payment_intent_id FROM orders WHERE id = ?', (order_id,)).fetchone()
        if order is None:
            return {'ok': False, 'error': f'order {order_id} not found'}
        if order['status'] == 'cancelled':
            return {'ok': False, 'error': 'order already cancelled'}
        amount = refund_amount_cents or order['total_cents']
        if amount <= 0 or amount > order['total_cents']:
            return {'ok': False, 'error': 'refund amount must be between 1 and the order total'}
        refund = stripe.Refund.create(payment_intent=order['payment_intent_id'], amount=amount, reason=reason, metadata={'order_id': order_id})
        with conn:
            voided = conn.execute('DELETE FROM tickets WHERE order_id = ?', (order_id,)).rowcount
            conn.execute("UPDATE orders SET status = 'cancelled' WHERE id = ?", (order_id,))
    finally:
        conn.close()
    result = {'ok': True, 'order_id': order_id, 'tickets_voided': voided, 'refund_id': refund.id, 'refund_status': refund.status, 'refunded_cents': amount, 'full_refund': amount == order['total_cents']}
    return result

