import sqlite3
from datetime import datetime, timezone
from langchain_core.tools import tool
_DB_PATH = 'calendar.db'

def _parse_iso(value):
    try:
        return datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return None

@tool
def move_event_to_calendar_and_reschedule(event_id: int, target_calendar_id: int, new_start_iso: str, new_end_iso: str) -> dict:
    if not isinstance(event_id, int) or event_id <= 0:
        return {'ok': False, 'error': 'event_id must be a positive integer.'}
    if not isinstance(target_calendar_id, int) or target_calendar_id <= 0:
        return {'ok': False, 'error': 'target_calendar_id must be a positive integer.'}
    start = _parse_iso(new_start_iso)
    end = _parse_iso(new_end_iso)
    if start is None or end is None:
        return {'ok': False, 'error': 'Start and end must be valid ISO 8601 datetimes.'}
    if end <= start:
        return {'ok': False, 'error': 'End time must be after start time.'}
    if (end - start).days > 14:
        return {'ok': False, 'error': 'Events longer than 14 days are not allowed.'}
    now = datetime.now(timezone.utc).isoformat()
    conn = sqlite3.connect(_DB_PATH)
    try:
        with conn:
            moved = conn.execute('UPDATE events SET calendar_id = ? WHERE id = ? AND calendar_id != ?', (target_calendar_id, event_id, target_calendar_id))
            if moved.rowcount == 0:
                return {'ok': False, 'error': 'Event not found or already on the target calendar.'}
            conn.execute('UPDATE events SET start_time = ?, end_time = ?, updated_at = ? WHERE id = ?', (start.isoformat(), end.isoformat(), now, event_id))
    except sqlite3.IntegrityError:
        return {'ok': False, 'error': 'Target calendar does not exist.'}
    finally:
        conn.close()
    return {'ok': True, 'event_id': event_id, 'calendar_id': target_calendar_id, 'start_time': start.isoformat(), 'end_time': end.isoformat()}

import sqlite3
from langchain_core.tools import tool
_DB_PATH = 'calendar.db'

@tool
def archive_event_and_clear_reminders(event_id: int) -> dict:
    if not isinstance(event_id, int) or event_id <= 0:
        return {'ok': False, 'error': 'event_id must be a positive integer.'}
    conn = sqlite3.connect(_DB_PATH)
    try:
        with conn:
            copied = conn.execute('INSERT INTO archived_events SELECT * FROM events WHERE id = ?', (event_id,))
            if copied.rowcount == 0:
                return {'ok': False, 'error': f'Event {event_id} not found.'}
            conn.execute('DELETE FROM events WHERE id = ?', (event_id,))
            cleared = conn.execute('DELETE FROM reminders WHERE event_id = ? AND sent = 0', (event_id,))
    except sqlite3.IntegrityError:
